def forward(groups):
    try:
        speeds = [int(groups[i]) for i in range(len(groups)) if groups[i].isdigit()]
        return {'stored': speeds, 'layout': []}
    except Exception as e:
        raise ValueError(f"Error processing groups: {e}")

def inverse(record):
    try:
        speeds = [str(v) for v in record['stored']]
        return '(' + ' '.join(speeds) + ')'
    except Exception as e:
        raise ValueError(f"Error reconstructing record: {e}")
